def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 5 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)

            # Fill the enclosed area and the single gap in the top edge.
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    if out[y][x] == 0:
                        out[y][x] = 2

            gaps = [x for x in range(c0 + 1, c1) if grid[r0][x] == 0]
            if len(gaps) == 1 and r0 > 0:
                gap = gaps[0]
                out[r0][gap] = 2

                # Extend from the gap along the row above, toward the opposite side.
                if gap < (c0 + c1) / 2:
                    xs = range(gap, w)
                else:
                    xs = range(gap, -1, -1)
                for x in xs:
                    out[r0 - 1][x] = 2

    return out
